CREATE TABLE shops (id text PRIMARY KEY, name text NOT NULL, country text NOT NULL, payout_email text NOT NULL);
CREATE TABLE products (id text PRIMARY KEY, shop_id text NOT NULL REFERENCES shops, name text NOT NULL, hts_code text NOT NULL, origin text NOT NULL, image_url text NOT NULL, list_price integer NOT NULL CHECK(list_price>0));
CREATE TABLE variants (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products, label text NOT NULL, weight_g integer NOT NULL CHECK(weight_g>0), stock integer NOT NULL CHECK(stock>=0), days_on_shelf integer NOT NULL CHECK(days_on_shelf>=0), unit_cost integer NOT NULL CHECK(unit_cost>=0), lowest_price integer NOT NULL CHECK(lowest_price>=unit_cost));
CREATE TABLE shop_extras (id text PRIMARY KEY, shop_id text NOT NULL REFERENCES shops, name text NOT NULL, unit_cost integer NOT NULL CHECK(unit_cost>=0), stock integer NOT NULL CHECK(stock>=0));
CREATE TABLE freight_options (id text PRIMARY KEY, shop_id text NOT NULL REFERENCES shops, kind text NOT NULL, departs_on date, transit_days integer NOT NULL CHECK(transit_days>=0), price_rule jsonb NOT NULL, cost_rule jsonb NOT NULL);
CREATE TABLE communities (id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE pools (id uuid PRIMARY KEY, community_id uuid REFERENCES communities, shop_id text NOT NULL REFERENCES shops, organizer_id text NOT NULL, state text NOT NULL DEFAULT 'OPEN' CHECK(state IN ('OPEN','LOCKED','NEGOTIATING','AGREED','CHARGED','SHIPPED','DELIVERED','NO_DEAL','VOIDED','NOT_SHIPPED','REFUNDED')), lock_at timestamptz NOT NULL, deal_deadline timestamptz, ship_by timestamptz NOT NULL, deliver_to jsonb NOT NULL, CHECK(ship_by>lock_at));
CREATE TABLE members (id uuid PRIMARY KEY, pool_id uuid NOT NULL REFERENCES pools, display_name text NOT NULL, raw_text text NOT NULL, max_cents integer NOT NULL CHECK(max_cents>0), state text NOT NULL DEFAULT 'JOINED', joined_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE member_items (id uuid PRIMARY KEY, member_id uuid NOT NULL REFERENCES members, product_id text NOT NULL REFERENCES products, qty integer NOT NULL CHECK(qty>0), preferred_variant_id text NOT NULL REFERENCES variants);
CREATE TABLE member_rules (id uuid PRIMARY KEY, member_id uuid NOT NULL REFERENCES members, kind text NOT NULL CHECK(kind IN ('variant_swap','slow_shipping')), params jsonb NOT NULL, source_span text NOT NULL);
CREATE TABLE holds (id uuid PRIMARY KEY, member_id uuid NOT NULL REFERENCES members, order_id text NOT NULL UNIQUE, authorization_id text UNIQUE, amount_cents integer NOT NULL CHECK(amount_cents>0), status text NOT NULL, honor_until timestamptz, expires_at timestamptz);
CREATE UNIQUE INDEX one_active_hold ON holds(member_id) WHERE status IN ('CREATED','APPROVED','AUTHORIZED','PENDING');
CREATE TABLE rounds (id uuid PRIMARY KEY, pool_id uuid NOT NULL REFERENCES pools, n integer NOT NULL CHECK(n BETWEEN 1 AND 3), actor text NOT NULL CHECK(actor IN ('buyer','seller')), offer jsonb NOT NULL, message text NOT NULL, valid boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE questions (id uuid PRIMARY KEY, member_id uuid NOT NULL UNIQUE REFERENCES members, round_id uuid NOT NULL REFERENCES rounds, payload jsonb NOT NULL, answer jsonb, default_answer jsonb NOT NULL, deadline timestamptz NOT NULL);
CREATE TABLE deals (id uuid PRIMARY KEY, pool_id uuid NOT NULL UNIQUE REFERENCES pools, terms jsonb NOT NULL, version integer NOT NULL CHECK(version>0), accepted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE allocations (id uuid PRIMARY KEY, deal_id uuid NOT NULL REFERENCES deals, member_id uuid NOT NULL REFERENCES members, lines jsonb NOT NULL, freight integer NOT NULL CHECK(freight>=0), duty integer NOT NULL CHECK(duty>=0), fee integer NOT NULL CHECK(fee>=0), tax integer NOT NULL CHECK(tax>=0), total integer NOT NULL CHECK(total>0), UNIQUE(deal_id,member_id));
CREATE TABLE payment_ops (id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('order','authorize','capture','void','refund','payout')), member_id uuid REFERENCES members, pool_id uuid NOT NULL REFERENCES pools, request_id text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN ('ready','inflight','unknown','pending','completed','failed')), provider_ref text, request jsonb NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX payment_ops_member ON payment_ops(member_id,kind);
CREATE TABLE payouts (id uuid PRIMARY KEY, pool_id uuid NOT NULL UNIQUE REFERENCES pools, batch_id text NOT NULL UNIQUE, amount_cents integer NOT NULL CHECK(amount_cents>0), status text NOT NULL);
CREATE TABLE shipments (id uuid PRIMARY KEY, pool_id uuid NOT NULL UNIQUE REFERENCES pools, carrier text NOT NULL CHECK(length(carrier)>0), tracking_number text NOT NULL CHECK(length(tracking_number)>0), shipped_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_events (id uuid PRIMARY KEY, event_id text NOT NULL UNIQUE, type text NOT NULL, raw jsonb NOT NULL, raw_body bytea NOT NULL, headers jsonb NOT NULL, verified boolean NOT NULL DEFAULT false, processed_at timestamptz, provider_ref text);
CREATE TABLE jobs (id bigserial PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL, dedupe_key text NOT NULL UNIQUE, run_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, attempts integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'ready' CHECK(status IN ('ready','running','done','recovery')), error text);
CREATE INDEX jobs_ready ON jobs(run_at,id) WHERE status IN ('ready','running');
CREATE TABLE rate_table (id uuid PRIMARY KEY, origin text NOT NULL, hts_prefix text NOT NULL, duty_bp integer NOT NULL CHECK(duty_bp>=0), source_url text NOT NULL, as_of date NOT NULL, UNIQUE(origin,hts_prefix,as_of));
CREATE TABLE bench_runs (id uuid PRIMARY KEY, strategy text NOT NULL CHECK(strategy IN ('A','B','C','D')), seed integer NOT NULL, metrics jsonb NOT NULL);
